CREATE OR REPLACE FUNCTION "asset_cost_basis_quantity_reduction_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.quantity < OLD.quantity) THEN
        UPDATE asset_cost_basis SET total_minor_units = REMAINING_COST_BASIS(total_minor_units, OLD.quantity, NEW.quantity) WHERE holding_id = NEW.holding_id;
    END IF;
    RETURN NULL;
END $$;
