BEGIN
    IF (NOT NEW.cash IS NOT DISTINCT FROM OLD.cash AND EXISTS(SELECT 1 FROM company_accounts WHERE user_id = NEW.user_id)) THEN
        UPDATE issuer_cash_accounts SET balance = TRUNC(ROUND(CAST(NEW.cash AS DECIMAL), CAST(0 AS INT))) WHERE company_code = (SELECT company_code FROM company_accounts WHERE user_id = NEW.user_id) AND balance <> TRUNC(ROUND(CAST(NEW.cash AS DECIMAL), CAST(0 AS INT)));
    END IF;
    RETURN NULL;
END $$;
