CREATE OR REPLACE FUNCTION "fin_post_balanced_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.status = 'posted') THEN
        IF ((SELECT COUNT(*) FROM financial_lines WHERE entry_id = NEW.entry_id) < 2 OR (SELECT COALESCE(SUM(amount), 0) FROM financial_lines WHERE entry_id = NEW.entry_id) <> 0) THEN
            RAISE EXCEPTION USING MESSAGE = 'unbalanced financial entry', ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END $$;
