CREATE TRIGGER "guard_user_assets_quantity_update" BEFORE UPDATE OF "quantity" ON "user_assets" FOR EACH ROW WHEN (NEW.quantity IS NULL OR (NOT NEW.quantity IS NULL AND (NOT CASE WHEN CAST(PG_TYPEOF(NEW.quantity) AS TEXT) IN ('bigint', 'integer') THEN 'integer' WHEN CAST(PG_TYPEOF(NEW.quantity) AS TEXT) IN ('double precision', 'numeric') THEN 'real' ELSE 'text' END IN ('integer', 'real') OR NEW.quantity > 9007199254740991 OR NEW.quantity < -9007199254740991))) EXECUTE FUNCTION raise_abort('숫자 저장 오류: user_assets.quantity 값이 비었거나(NaN) 무한대·허용 범위를 넘었습니다.');
CREATE TRIGGER "guard_users_cash_insert" BEFORE INSERT ON "users" FOR EACH ROW WHEN (NEW.cash IS NOT DISTINCT FROM NULL OR (NOT NEW.cash IS NOT DISTINCT FROM NULL AND (NOT CASE WHEN NEW.cash = TRUNC(NEW.cash) THEN 'integer' ELSE 'real' END IN ('integer', 'real') OR NEW.cash > 1000000000000000000000000 OR NEW.cash < (0 - 1000000000000000000000000)))) EXECUTE FUNCTION raise_abort('숫자 저장 오류: users.cash 값이 비었거나(NaN) 무한대·허용 범위를 넘었습니다.');
CREATE TRIGGER "guard_users_cash_minor_insert" BEFORE INSERT ON "users" FOR EACH ROW WHEN (NEW.cash_minor IS NOT DISTINCT FROM NULL OR (NOT NEW.cash_minor IS NOT DISTINCT FROM NULL AND (NOT CASE WHEN NEW.cash_minor = TRUNC(NEW.cash_minor) THEN 'integer' ELSE 'real' END IN ('integer', 'real') OR NEW.cash_minor > 1000000000000000000000000000000 OR NEW.cash_minor < (0 - 1000000000000000000000000000000)))) EXECUTE FUNCTION raise_abort('숫자 저장 오류: users.cash_minor 값이 비었거나(NaN) 무한대·허용 범위를 넘었습니다.');
CREATE TRIGGER "guard_users_cash_minor_update" BEFORE UPDATE OF "cash_minor" ON "users" FOR EACH ROW WHEN (NEW.cash_minor IS NOT DISTINCT FROM NULL OR (NOT NEW.cash_minor IS NOT DISTINCT FROM NULL AND (NOT CASE WHEN NEW.cash_minor = TRUNC(NEW.cash_minor) THEN 'integer' ELSE 'real' END IN ('integer', 'real') OR NEW.cash_minor > 1000000000000000000000000000000 OR NEW.cash_minor < (0 - 1000000000000000000000000000000)))) EXECUTE FUNCTION raise_abort('숫자 저장 오류: users.cash_minor 값이 비었거나(NaN) 무한대·허용 범위를 넘었습니다.');
CREATE TRIGGER "guard_users_cash_update" BEFORE UPDATE OF "cash" ON "users" FOR EACH ROW WHEN (NEW.cash IS NOT DISTINCT FROM NULL OR (NOT NEW.cash IS NOT DISTINCT FROM NULL AND (NOT CASE WHEN NEW.cash = TRUNC(NEW.cash) THEN 'integer' ELSE 'real' END IN ('integer', 'real') OR NEW.cash > 1000000000000000000000000 OR NEW.cash < (0 - 1000000000000000000000000)))) EXECUTE FUNCTION raise_abort('숫자 저장 오류: users.cash 값이 비었거나(NaN) 무한대·허용 범위를 넘었습니다.');
CREATE OR REPLACE FUNCTION "issuer_cash_to_company_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.balance IS NOT DISTINCT FROM OLD.balance) THEN
        UPDATE users SET cash = NEW.balance WHERE user_id = (SELECT user_id FROM company_accounts WHERE company_code = NEW.company_code) AND cash <> NEW.balance;
    END IF;
    RETURN NULL;
END $$;
CREATE TRIGGER "issuer_cash_to_company" AFTER UPDATE OF "balance" ON "issuer_cash_accounts" FOR EACH ROW EXECUTE FUNCTION "issuer_cash_to_company_fn"();
CREATE TRIGGER "loan_ecl_assessments_no_delete" BEFORE DELETE ON "loan_ecl_assessments" FOR EACH ROW EXECUTE FUNCTION raise_abort('ECL assessments are append-only');
CREATE TRIGGER "loan_ecl_assessments_no_update" BEFORE UPDATE ON "loan_ecl_assessments" FOR EACH ROW EXECUTE FUNCTION raise_abort('ECL assessments are append-only');
CREATE OR REPLACE FUNCTION "market_exchange_indices_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO market_exchanges (exchange_id, index_value, index_updated_epoch, status, updated_epoch) VALUES (NEW.exchange_id, NEW.index_value, NEW.updated_epoch, 'open', NEW.updated_epoch) ON CONFLICT(exchange_id) DO UPDATE SET index_value = excluded.index_value, index_updated_epoch = excluded.index_updated_epoch;
    RETURN NEW;
END $$;
CREATE TRIGGER "market_exchange_indices_insert" INSTEAD OF INSERT ON "market_exchange_indices" FOR EACH ROW EXECUTE FUNCTION "market_exchange_indices_insert_fn"();
CREATE OR REPLACE FUNCTION "market_exchange_indices_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE market_exchanges SET index_value = NEW.index_value, index_updated_epoch = NEW.updated_epoch WHERE exchange_id = OLD.exchange_id;
    RETURN NEW;
END $$;
CREATE TRIGGER "market_exchange_indices_update" INSTEAD OF UPDATE ON "market_exchange_indices" FOR EACH ROW EXECUTE FUNCTION "market_exchange_indices_update_fn"();
CREATE OR REPLACE FUNCTION "organization_company_after_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO organizations (organization_code, name, industry, country_code, status) SELECT NEW.company_code, COALESCE(NEW.name, ''), COALESCE(NEW.industry, ''), COALESCE((SELECT nationality FROM market_exchanges WHERE exchange_id = NEW.exchange_id), NEW.nationality), COALESCE(NEW.status, 'active') WHERE COALESCE(NEW.share_class, 'common') = 'common' ON CONFLICT DO NOTHING;
    INSERT INTO share_issuances (organization_code, class_name, share_class, voting_rights_per_share) SELECT NEW.company_code, COALESCE(NEW.name, NEW.company_code) || ' 보통주', 'common', '1' WHERE COALESCE(NEW.share_class, 'common') = 'common' AND NEW.share_issuance_id IS NULL;
    UPDATE company SET share_issuance_id = LASTVAL() WHERE company_code = NEW.company_code AND COALESCE(NEW.share_class, 'common') = 'common' AND NEW.share_issuance_id IS NULL;
    INSERT INTO share_issuances (organization_code, class_name, share_class, voting_rights_per_share) SELECT NEW.parent_company_code, COALESCE(NEW.name, NEW.company_code) || ' 우선주', 'preferred', '1' WHERE NEW.share_class = 'preferred' AND NEW.share_issuance_id IS NULL AND NOT NEW.parent_company_code IS NULL AND EXISTS(SELECT 1 FROM organizations WHERE organization_code = NEW.parent_company_code);
    UPDATE company SET share_issuance_id = LASTVAL() WHERE company_code = NEW.company_code AND NEW.share_class = 'preferred' AND NEW.share_issuance_id IS NULL AND NOT NEW.parent_company_code IS NULL AND EXISTS(SELECT 1 FROM organizations WHERE organization_code = NEW.parent_company_code);
    RETURN NULL;
END $$;
CREATE TRIGGER "organization_company_after_insert" AFTER INSERT ON "company" FOR EACH ROW EXECUTE FUNCTION "organization_company_after_insert_fn"();
CREATE OR REPLACE FUNCTION "organization_company_after_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE organizations SET name = COALESCE(NEW.name, ''), industry = COALESCE(NEW.industry, ''), country_code = CASE WHEN NOT NEW.exchange_id IS NOT DISTINCT FROM OLD.exchange_id THEN COALESCE((SELECT nationality FROM market_exchanges WHERE exchange_id = NEW.exchange_id), NEW.nationality) WHEN NOT NEW.nationality IS NOT DISTINCT FROM OLD.nationality THEN NEW.nationality ELSE country_code END, updated_epoch = CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT) WHERE organization_code = NEW.company_code AND COALESCE(NEW.share_class, 'common') = 'common';
    UPDATE share_issuances SET rights_json = JSON_OBJECT('dividend_priority': NEW.dividend_priority, 'cumulative_dividend': NEW.cumulative_dividend, 'dividend_mode': NEW.dividend_mode, 'dividend_per_share': CAST(NEW.dividend_per_share AS TEXT), 'dividend_percent': CAST(NEW.dividend_percent AS TEXT), 'liquidation_value_per_share': CAST(NEW.liquidation_value_per_share AS TEXT), 'dividend_funding': NEW.dividend_funding, 'dividend_cycle_seconds': NEW.dividend_cycle_seconds, 'dividend_is_active': NEW.dividend_is_active), updated_epoch = CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT) WHERE issuance_id = NEW.share_issuance_id;
    RETURN NULL;
END $$;
CREATE TRIGGER "organization_company_after_update" AFTER UPDATE OF "name", "industry", "exchange_id", "nationality", "dividend_priority", "cumulative_dividend", "dividend_mode", "dividend_per_share", "dividend_percent", "dividend_cycle_seconds", "dividend_is_active", "liquidation_value_per_share", "dividend_funding" ON "company" FOR EACH ROW EXECUTE FUNCTION "organization_company_after_update_fn"();
CREATE TRIGGER "share_resolution_executions_delete_immutable" BEFORE DELETE ON "share_resolution_executions" FOR EACH ROW EXECUTE FUNCTION raise_abort('share resolution records are immutable');
CREATE TRIGGER "share_resolution_executions_update_immutable" BEFORE UPDATE ON "share_resolution_executions" FOR EACH ROW EXECUTE FUNCTION raise_abort('share resolution records are immutable');
CREATE TRIGGER "shareholder_resolutions_delete_immutable" BEFORE DELETE ON "shareholder_resolutions" FOR EACH ROW EXECUTE FUNCTION raise_abort('share resolution records are immutable');
CREATE TRIGGER "shareholder_resolutions_update_immutable" BEFORE UPDATE ON "shareholder_resolutions" FOR EACH ROW EXECUTE FUNCTION raise_abort('share resolution records are immutable');
CREATE OR REPLACE FUNCTION "trg_account_reference_price_from_legacy_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.reference_price IS NOT DISTINCT FROM NULL) THEN
        NEW."reference_price_minor_units" := TRUNC(ROUND(CAST((NEW.reference_price * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_account_reference_price_from_legacy" BEFORE INSERT ON "accounts" FOR EACH ROW EXECUTE FUNCTION "trg_account_reference_price_from_legacy_fn"();
CREATE OR REPLACE FUNCTION "trg_account_reference_price_legacy_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.reference_price IS NOT DISTINCT FROM NULL) THEN
        NEW."reference_price_minor_units" := TRUNC(ROUND(CAST((NEW.reference_price * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_account_reference_price_legacy_update" BEFORE UPDATE OF "reference_price", "quote_currency" ON "accounts" FOR EACH ROW EXECUTE FUNCTION "trg_account_reference_price_legacy_update_fn"();
CREATE OR REPLACE FUNCTION "trg_account_reference_price_minor_mirror_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.reference_price_minor_units IS NOT DISTINCT FROM OLD.reference_price_minor_units AND NOT NEW.reference_price_minor_units IS NOT DISTINCT FROM NULL) THEN
        NEW."reference_price" := CASE WHEN (NEW.reference_price_minor_units * 1.0) = TRUNC((NEW.reference_price_minor_units * 1.0)) AND (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) = TRUNC((CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) THEN TRUNC((NEW.reference_price_minor_units * 1.0) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) ELSE (NEW.reference_price_minor_units * 1.0) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) END;
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_account_reference_price_minor_mirror" BEFORE UPDATE OF "reference_price_minor_units" ON "accounts" FOR EACH ROW EXECUTE FUNCTION "trg_account_reference_price_minor_mirror_fn"();
CREATE OR REPLACE FUNCTION "trg_accounting_closing_mixed_precision_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((SELECT COUNT(DISTINCT decimal_places) FROM journal_entries AS e WHERE e.ledger_scope = NEW.ledger_scope AND e.entity_id = NEW.entity_id AND e.currency_code = NEW.currency_code AND e.recorded_epoch >= NEW.period_start_epoch AND e.recorded_epoch < NEW.period_end_epoch) > 1) THEN
        RAISE EXCEPTION USING MESSAGE = 'mixed currency precision in accounting period', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_accounting_closing_mixed_precision" BEFORE INSERT ON "accounting_period_closings" FOR EACH ROW EXECUTE FUNCTION "trg_accounting_closing_mixed_precision_fn"();
CREATE OR REPLACE FUNCTION "trg_accounting_closing_unbalanced_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (EXISTS(SELECT e.entry_id FROM journal_entries AS e LEFT JOIN journal_lines AS l ON l.entry_id = e.entry_id WHERE e.ledger_scope = NEW.ledger_scope AND e.entity_id = NEW.entity_id AND e.currency_code = NEW.currency_code AND e.recorded_epoch >= NEW.period_start_epoch AND e.recorded_epoch < NEW.period_end_epoch GROUP BY e.entry_id HAVING COUNT(l.line_id) < 2 OR SUM(l.debit_units) <> SUM(l.credit_units))) THEN
        RAISE EXCEPTION USING MESSAGE = 'unbalanced accounting period', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_accounting_closing_unbalanced" BEFORE INSERT ON "accounting_period_closings" FOR EACH ROW EXECUTE FUNCTION "trg_accounting_closing_unbalanced_fn"();
CREATE OR REPLACE FUNCTION "trg_accounting_entries_closed_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (EXISTS(SELECT 1 FROM accounting_period_closings AS c WHERE c.ledger_scope = NEW.ledger_scope AND c.entity_id = NEW.entity_id AND c.currency_code = NEW.currency_code AND NEW.recorded_epoch >= c.period_start_epoch AND NEW.recorded_epoch < c.period_end_epoch) OR EXISTS(SELECT 1 FROM journal_entries AS e JOIN accounting_period_closings AS c ON c.ledger_scope = e.ledger_scope AND c.entity_id = e.entity_id AND c.currency_code = e.currency_code AND e.recorded_epoch >= c.period_start_epoch AND e.recorded_epoch < c.period_end_epoch WHERE e.entry_id = NEW.entry_id OR (e.ledger_scope = NEW.ledger_scope AND e.entity_type = NEW.entity_type AND e.entity_id = NEW.entity_id AND e.source_key = NEW.source_key))) THEN
        RAISE EXCEPTION USING MESSAGE = 'closed accounting period', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_accounting_entries_closed_insert" BEFORE INSERT ON "journal_entries" FOR EACH ROW EXECUTE FUNCTION "trg_accounting_entries_closed_insert_fn"();
CREATE TRIGGER "trg_accounting_entries_delete_immutable" BEFORE DELETE ON "journal_entries" FOR EACH ROW EXECUTE FUNCTION raise_abort('common accounting journal is append-only');
CREATE OR REPLACE FUNCTION "trg_accounting_entries_insert_immutable_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (EXISTS(SELECT 1 FROM journal_entries AS e WHERE e.entry_id = NEW.entry_id OR (e.ledger_scope = NEW.ledger_scope AND e.entity_type = NEW.entity_type AND e.entity_id = NEW.entity_id AND e.source_key = NEW.source_key))) THEN
        RAISE EXCEPTION USING MESSAGE = 'common accounting journal is append-only', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_accounting_entries_insert_immutable" BEFORE INSERT ON "journal_entries" FOR EACH ROW EXECUTE FUNCTION "trg_accounting_entries_insert_immutable_fn"();
CREATE TRIGGER "trg_accounting_entries_update_immutable" BEFORE UPDATE ON "journal_entries" FOR EACH ROW EXECUTE FUNCTION raise_abort('common accounting journal is append-only');
CREATE OR REPLACE FUNCTION "trg_accounting_lines_closed_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (EXISTS(SELECT 1 FROM journal_entries AS e JOIN accounting_period_closings AS c ON c.ledger_scope = e.ledger_scope AND c.entity_id = e.entity_id AND c.currency_code = e.currency_code AND e.recorded_epoch >= c.period_start_epoch AND e.recorded_epoch < c.period_end_epoch WHERE e.entry_id = NEW.entry_id OR e.entry_id = (SELECT entry_id FROM journal_lines WHERE line_id = NEW.line_id))) THEN
        RAISE EXCEPTION USING MESSAGE = 'closed accounting period', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_accounting_lines_closed_insert" BEFORE INSERT ON "journal_lines" FOR EACH ROW EXECUTE FUNCTION "trg_accounting_lines_closed_insert_fn"();
CREATE TRIGGER "trg_accounting_lines_delete_immutable" BEFORE DELETE ON "journal_lines" FOR EACH ROW EXECUTE FUNCTION raise_abort('common accounting journal is append-only');
CREATE OR REPLACE FUNCTION "trg_accounting_lines_insert_immutable_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (EXISTS(SELECT 1 FROM journal_lines AS l WHERE l.line_id = NEW.line_id)) THEN
        RAISE EXCEPTION USING MESSAGE = 'common accounting journal is append-only', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_accounting_lines_insert_immutable" BEFORE INSERT ON "journal_lines" FOR EACH ROW EXECUTE FUNCTION "trg_accounting_lines_insert_immutable_fn"();
CREATE TRIGGER "trg_accounting_lines_update_immutable" BEFORE UPDATE ON "journal_lines" FOR EACH ROW EXECUTE FUNCTION raise_abort('common accounting journal is append-only');
CREATE TRIGGER "trg_accounting_period_closings_delete_immutable" BEFORE DELETE ON "accounting_period_closings" FOR EACH ROW EXECUTE FUNCTION raise_abort('accounting period closings are append-only');
CREATE OR REPLACE FUNCTION "trg_accounting_period_closings_insert_immutable_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (EXISTS(SELECT 1 FROM accounting_period_closings AS c WHERE c.closing_id = NEW.closing_id OR (c.ledger_scope = NEW.ledger_scope AND c.entity_id = NEW.entity_id AND c.currency_code = NEW.currency_code AND c.period_start_epoch = NEW.period_start_epoch AND c.period_end_epoch = NEW.period_end_epoch))) THEN
        RAISE EXCEPTION USING MESSAGE = 'accounting period closings are append-only', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_accounting_period_closings_insert_immutable" BEFORE INSERT ON "accounting_period_closings" FOR EACH ROW EXECUTE FUNCTION "trg_accounting_period_closings_insert_immutable_fn"();
CREATE TRIGGER "trg_accounting_period_closings_update_immutable" BEFORE UPDATE ON "accounting_period_closings" FOR EACH ROW EXECUTE FUNCTION raise_abort('accounting period closings are append-only');
CREATE TRIGGER "trg_accounts_balance_guard" BEFORE UPDATE OF "balance" ON "accounts" FOR EACH ROW WHEN (NEW.balance_units IS NOT DISTINCT FROM OLD.balance_units AND ABS((COALESCE(NEW.balance, 0) - CASE WHEN NEW.balance_units = TRUNC(NEW.balance_units) AND 1000000.0 = TRUNC(1000000.0) THEN TRUNC(NEW.balance_units / 1000000.0) ELSE NEW.balance_units / 1000000.0 END)) > 0.500001) EXECUTE FUNCTION raise_abort('Account balances are stored in balance_units; update balance_units instead');
CREATE OR REPLACE FUNCTION "trg_accounts_currency_money_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."balance" IS NOT DISTINCT FROM NULL OR NEW."balance" <> ROUND(CAST(((COALESCE(NEW."balance", 0)) + CASE WHEN (COALESCE(NEW."balance", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT))) OR (NEW."principal" IS NOT DISTINCT FROM NULL OR NEW."principal" <> ROUND(CAST(((COALESCE(NEW."principal", 0)) + CASE WHEN (COALESCE(NEW."principal", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT))) OR (NEW."insurance_paid" IS NOT DISTINCT FROM NULL OR NEW."insurance_paid" <> ROUND(CAST(((COALESCE(NEW."insurance_paid", 0)) + CASE WHEN (COALESCE(NEW."insurance_paid", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT))) OR (NEW."uninsured_claim" IS NOT DISTINCT FROM NULL OR NEW."uninsured_claim" <> ROUND(CAST(((COALESCE(NEW."uninsured_claim", 0)) + CASE WHEN (COALESCE(NEW."uninsured_claim", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT)))) THEN
        NEW."balance" := ROUND(CAST(((COALESCE(NEW."balance", 0)) + CASE WHEN (COALESCE(NEW."balance", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
        NEW."principal" := ROUND(CAST(((COALESCE(NEW."principal", 0)) + CASE WHEN (COALESCE(NEW."principal", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
        NEW."insurance_paid" := ROUND(CAST(((COALESCE(NEW."insurance_paid", 0)) + CASE WHEN (COALESCE(NEW."insurance_paid", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
        NEW."uninsured_claim" := ROUND(CAST(((COALESCE(NEW."uninsured_claim", 0)) + CASE WHEN (COALESCE(NEW."uninsured_claim", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_accounts_currency_money_insert" BEFORE INSERT ON "accounts" FOR EACH ROW EXECUTE FUNCTION "trg_accounts_currency_money_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_accounts_currency_money_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."balance" IS NOT DISTINCT FROM NULL OR NEW."balance" <> ROUND(CAST(((COALESCE(NEW."balance", 0)) + CASE WHEN (COALESCE(NEW."balance", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT))) OR (NEW."principal" IS NOT DISTINCT FROM NULL OR NEW."principal" <> ROUND(CAST(((COALESCE(NEW."principal", 0)) + CASE WHEN (COALESCE(NEW."principal", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT))) OR (NEW."insurance_paid" IS NOT DISTINCT FROM NULL OR NEW."insurance_paid" <> ROUND(CAST(((COALESCE(NEW."insurance_paid", 0)) + CASE WHEN (COALESCE(NEW."insurance_paid", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT))) OR (NEW."uninsured_claim" IS NOT DISTINCT FROM NULL OR NEW."uninsured_claim" <> ROUND(CAST(((COALESCE(NEW."uninsured_claim", 0)) + CASE WHEN (COALESCE(NEW."uninsured_claim", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT)))) THEN
        NEW."balance" := ROUND(CAST(((COALESCE(NEW."balance", 0)) + CASE WHEN (COALESCE(NEW."balance", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
        NEW."principal" := ROUND(CAST(((COALESCE(NEW."principal", 0)) + CASE WHEN (COALESCE(NEW."principal", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
        NEW."insurance_paid" := ROUND(CAST(((COALESCE(NEW."insurance_paid", 0)) + CASE WHEN (COALESCE(NEW."insurance_paid", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
        NEW."uninsured_claim" := ROUND(CAST(((COALESCE(NEW."uninsured_claim", 0)) + CASE WHEN (COALESCE(NEW."uninsured_claim", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
