CREATE OR REPLACE FUNCTION "trg_accounts_currency_quantum_change_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.balance_units % (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1000000 WHEN 1 THEN 100000 ELSE 10000 END) <> 0) THEN
        RAISE EXCEPTION USING MESSAGE = 'Account balance must align to destination currency minor units', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
