CREATE OR REPLACE FUNCTION "trg_aml_amount_minor_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW."amount_decimal_places" := COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0);
    NEW."amount_minor_units" := TRUNC(ROUND(CAST((NEW.amount * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
    RETURN NEW;
END $$;
