CREATE OR REPLACE FUNCTION "trg_aml_amount_minor_mirror_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.amount_minor_units IS NOT DISTINCT FROM OLD.amount_minor_units) THEN
        NEW."amount" := CASE WHEN (NEW.amount_minor_units * 1.0) = TRUNC((NEW.amount_minor_units * 1.0)) AND (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) = TRUNC((CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) THEN TRUNC((NEW.amount_minor_units * 1.0) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) ELSE (NEW.amount_minor_units * 1.0) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) END;
    END IF;
    RETURN NEW;
END $$;
