BEGIN
    IF (NEW.cash_minor_units IS NOT DISTINCT FROM NULL) THEN
        NEW."cash_currency_code" := COALESCE((SELECT currency_code FROM country_currencies WHERE nationality = (SELECT nationality FROM users WHERE user_id = (SELECT user_id FROM bank_accounts WHERE issuer = NEW.issuer))), BASE_CURRENCY_CODE());
        NEW."cash_decimal_places" := COALESCE((SELECT decimal_places FROM currencies WHERE code = COALESCE((SELECT currency_code FROM country_currencies WHERE nationality = (SELECT nationality FROM users WHERE user_id = (SELECT user_id FROM bank_accounts WHERE issuer = NEW.issuer))), BASE_CURRENCY_CODE())), 0);
        NEW."cash_minor_units" := TRUNC(ROUND(CAST((NEW.cash * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = COALESCE((SELECT currency_code FROM country_currencies WHERE nationality = (SELECT nationality FROM users WHERE user_id = (SELECT user_id FROM bank_accounts WHERE issuer = NEW.issuer))), BASE_CURRENCY_CODE())), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
    END IF;
    RETURN NEW;
END $$;
