CREATE OR REPLACE FUNCTION "trg_country_credit_scenario_seed_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO credit_risk_scenarios (nationality, scenario_key, probability, pd_multiplier, lgd_multiplier) VALUES (NEW.nationality, 'optimistic', 0.20, 0.80, 0.90), (NEW.nationality, 'base', 0.60, 1.00, 1.00), (NEW.nationality, 'downside', 0.20, 2.00, 1.15) ON CONFLICT DO NOTHING;
    RETURN NULL;
END $$;
