    UPDATE users SET cash_minor = TRUNC(ROUND(CAST((COALESCE(cash, 0) * (CASE (SELECT COALESCE(MAX(c.decimal_places), 0) FROM country_currencies AS n JOIN currencies AS c ON c.code = n.currency_code WHERE n.nationality = nationality) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) WHERE nationality = NEW.nationality;
    RETURN NULL;
END $$;
