CREATE OR REPLACE FUNCTION "trg_country_floating_reprice_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE bank_products SET interest_rate = LEAST(COALESCE(rate_cap, 100), GREATEST(CASE WHEN negative_rate_allowed = 1 THEN -100 ELSE rate_floor END, NEW.base_rate + base_rate_spread + maturity_spread + promotional_adjustment + COALESCE((SELECT competition_adjustment FROM financial_institutions WHERE issuer = saving.issuer), 0))) WHERE (rate_type = 'floating' AND benchmark_key = 'policy' AND rate_nationality = NEW.nationality) AND saving.kind = 'deposit';
    UPDATE bank_products SET interest_rate = LEAST(NEW.legal_max_rate, COALESCE(rate_cap, 100), GREATEST(rate_floor, NEW.base_rate + base_rate_spread + maturity_spread + promotional_adjustment + COALESCE((SELECT funding_spread + operating_cost_spread + liquidity_spread + target_margin + competition_adjustment FROM financial_institutions WHERE issuer = liability.issuer), 1.7))) WHERE (rate_type = 'floating' AND benchmark_key = 'policy' AND rate_nationality = NEW.nationality) AND liability.kind = 'loan';
    RETURN NULL;
END $$;
CREATE TRIGGER "trg_country_floating_reprice" AFTER UPDATE OF "base_rate", "legal_max_rate" ON "country_currencies" FOR EACH ROW EXECUTE FUNCTION "trg_country_floating_reprice_fn"();
CREATE OR REPLACE FUNCTION "trg_country_legal_max_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE bank_products SET interest_rate = LEAST(interest_rate, NEW.legal_max_rate) WHERE rate_nationality = NEW.nationality AND liability.kind = 'loan';
    UPDATE bank_products SET interest_rate = LEAST(interest_rate, (SELECT MIN(c.legal_max_rate) FROM country_currencies AS c WHERE c.currency_code = liability.quote_currency)) WHERE (rate_nationality IS NULL AND quote_currency = NEW.currency_code) AND liability.kind = 'loan';
    UPDATE loans SET contract_rate = LEAST(contract_rate, NEW.legal_max_rate), contract_effective_rate = CASE WHEN contract_rate > NEW.legal_max_rate THEN NULL ELSE contract_effective_rate END, contract_apr = CASE WHEN contract_rate > NEW.legal_max_rate THEN NULL ELSE contract_apr END WHERE rate_nationality = NEW.nationality;
    RETURN NULL;
END $$;
CREATE TRIGGER "trg_country_legal_max_insert" AFTER INSERT ON "country_currencies" FOR EACH ROW EXECUTE FUNCTION "trg_country_legal_max_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_country_legal_max_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    UPDATE bank_products SET interest_rate = LEAST(interest_rate, NEW.legal_max_rate) WHERE rate_nationality = NEW.nationality AND liability.kind = 'loan';
    UPDATE bank_products SET interest_rate = LEAST(interest_rate, (SELECT MIN(c.legal_max_rate) FROM country_currencies AS c WHERE c.currency_code = liability.quote_currency)) WHERE (rate_nationality IS NULL AND quote_currency = NEW.currency_code) AND liability.kind = 'loan';
    UPDATE loans SET contract_rate = LEAST(contract_rate, NEW.legal_max_rate), contract_effective_rate = CASE WHEN contract_rate > NEW.legal_max_rate THEN NULL ELSE contract_effective_rate END, contract_apr = CASE WHEN contract_rate > NEW.legal_max_rate THEN NULL ELSE contract_apr END WHERE rate_nationality = NEW.nationality;
    RETURN NULL;
END $$;
