CREATE OR REPLACE FUNCTION "trg_country_market_curve_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO market_rate_curve VALUES (NEW.nationality, 'funding', 30, NEW.base_rate + 0.20, 0.85, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'funding', 90, NEW.base_rate + 0.35, 0.80, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'funding', 365, NEW.base_rate + 0.55, 0.70, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'bank_bond', 90, NEW.base_rate + 0.45, 0.90, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'bank_bond', 365, NEW.base_rate + 0.75, 0.85, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'bank_bond', 1095, NEW.base_rate + 1.10, 0.75, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'treasury', 30, NEW.base_rate + 0.05, 0.95, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'treasury', 90, NEW.base_rate + 0.15, 0.90, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'treasury', 365, NEW.base_rate + 0.35, 0.85, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'treasury', 1095, NEW.base_rate + 0.65, 0.75, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'treasury', 3650, NEW.base_rate + 1.00, 0.60, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)) ON CONFLICT DO NOTHING;
    INSERT INTO market_rate_pressure VALUES (NEW.nationality, 'funding', 0, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'bank_bond', 0, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)), (NEW.nationality, 'treasury', 0, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)) ON CONFLICT DO NOTHING;
