CREATE OR REPLACE FUNCTION "trg_country_market_curve_policy_move_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.base_rate IS NOT DISTINCT FROM OLD.base_rate) THEN
        UPDATE market_rate_curve SET annual_rate = GREATEST(-100, LEAST(100, annual_rate + (NEW.base_rate - OLD.base_rate) * pass_through)), updated_epoch = CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT) WHERE nationality = NEW.nationality;
    END IF;
    RETURN NULL;
END $$;
CREATE TRIGGER "trg_country_market_curve_policy_move" AFTER UPDATE OF "base_rate" ON "country_currencies" FOR EACH ROW EXECUTE FUNCTION "trg_country_market_curve_policy_move_fn"();
