    INSERT INTO country_rate_history_events (operation, nationality, rate_key, before_percent, after_percent, before_epoch, after_epoch, before_actor, after_actor, recorded_epoch) VALUES ('delete', COALESCE(NULL, OLD.nationality), COALESCE(NULL, OLD.rate_key), OLD.annual_percent, NULL, OLD.effective_epoch, NULL, OLD.changed_by, NULL, ((EXTRACT(EPOCH FROM CURRENT_TIMESTAMP) / 86400.0 + 2440587.5) - 2440587.5) * 86400.0);
    RETURN NULL;
END $$;
