CREATE OR REPLACE FUNCTION "trg_currency_places_rescale_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.decimal_places IS NOT DISTINCT FROM OLD.decimal_places) THEN
        UPDATE users SET cash_minor = TRUNC(ROUND(CAST((COALESCE(cash, 0) * (CASE (SELECT COALESCE(MAX(c.decimal_places), 0) FROM country_currencies AS n JOIN currencies AS c ON c.code = n.currency_code WHERE n.nationality = nationality) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) WHERE nationality IN (SELECT nationality FROM country_currencies WHERE currency_code = NEW.code);
    END IF;
    RETURN NULL;
END $$;
