CREATE OR REPLACE FUNCTION "trg_customer_account_ledger_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.balance_minor_units <> 0 AND NOT NEW.user_id IS NULL) THEN
        INSERT INTO customer_wallet_ledger (source_key, user_id, source_type, source_account, currency_code, decimal_places, delta_minor_units, balance_minor_units, recorded_epoch) VALUES ('insert:account:' || NEW.account_number, NEW.user_id, 'account', NEW.account_number, NEW.quote_currency, NEW.balance_decimal_places, NEW.balance_minor_units, NEW.balance_minor_units, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT)) ON CONFLICT DO NOTHING;
    END IF;
    RETURN NULL;
END $$;
