CREATE OR REPLACE FUNCTION "trg_customer_account_ledger_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.balance_minor_units <> OLD.balance_minor_units AND NOT NEW.user_id IS NULL) THEN
        INSERT INTO customer_wallet_ledger (source_key, user_id, source_type, source_account, currency_code, decimal_places, delta_minor_units, balance_minor_units, recorded_epoch) VALUES ('change:account:' || NEW.account_number || ':' || CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT) || ':' || SUBSTRING(MD5(CAST(CAST(FLOOR(RANDOM() * 9007199254740991) AS BIGINT) AS TEXT) || CAST(CLOCK_TIMESTAMP() AS TEXT)) FROM 1 FOR 16), NEW.user_id, 'account', NEW.account_number, NEW.quote_currency, NEW.balance_decimal_places, (NEW.balance_minor_units - OLD.balance_minor_units), NEW.balance_minor_units, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT));
    END IF;
    RETURN NULL;
END $$;
CREATE TRIGGER "trg_customer_account_ledger_update" AFTER UPDATE OF "balance_minor_units" ON "accounts" FOR EACH ROW EXECUTE FUNCTION "trg_customer_account_ledger_update_fn"();
CREATE OR REPLACE FUNCTION "trg_customer_cash_ledger_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.cash_minor <> 0) THEN
