        INSERT INTO customer_wallet_ledger (source_key, user_id, source_type, source_account, currency_code, decimal_places, delta_minor_units, balance_minor_units, recorded_epoch) SELECT 'change:cash:' || NEW.user_id || ':' || CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT) || ':' || SUBSTRING(MD5(CAST(CAST(FLOOR(RANDOM() * 9007199254740991) AS BIGINT) AS TEXT) || CAST(CLOCK_TIMESTAMP() AS TEXT)) FROM 1 FOR 16), NEW.user_id, 'cash', NEW.user_id, COALESCE(n.currency_code, 'NWX'), COALESCE(c.decimal_places, 0), (NEW.cash_minor - OLD.cash_minor), NEW.cash_minor, CAST(EXTRACT(epoch FROM CURRENT_TIMESTAMP) AS BIGINT) FROM (SELECT 1) LEFT JOIN country_currencies AS n ON n.nationality = NEW.nationality LEFT JOIN currencies AS c ON c.code = n.currency_code;
    END IF;
    RETURN NULL;
END $$;
