CREATE OR REPLACE FUNCTION "trg_customer_wallet_common_post_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO journal_entries (ledger_scope, entity_type, entity_id, source_key, currency_code, decimal_places, recorded_epoch, description) VALUES ('customer', 'wallet_holder', NEW.user_id, 'wallet:' || NEW.entry_id, NEW.currency_code, NEW.decimal_places, NEW.recorded_epoch, NEW.source_type || ' balance movement');
    INSERT INTO journal_lines (entry_id, account_code, debit_units, credit_units) SELECT entry_id, 'customer_funds_payable', CASE WHEN NEW.delta_minor_units < 0 THEN (0 - NEW.delta_minor_units) ELSE 0 END, CASE WHEN NEW.delta_minor_units > 0 THEN NEW.delta_minor_units ELSE 0 END FROM journal_entries WHERE ledger_scope = 'customer' AND entity_type = 'wallet_holder' AND entity_id = NEW.user_id AND source_key = 'wallet:' || NEW.entry_id;
    INSERT INTO journal_lines (entry_id, account_code, debit_units, credit_units) SELECT entry_id, 'wallet_clearing', CASE WHEN NEW.delta_minor_units > 0 THEN NEW.delta_minor_units ELSE 0 END, CASE WHEN NEW.delta_minor_units < 0 THEN (0 - NEW.delta_minor_units) ELSE 0 END FROM journal_entries WHERE ledger_scope = 'customer' AND entity_type = 'wallet_holder' AND entity_id = NEW.user_id AND source_key = 'wallet:' || NEW.entry_id;
    RETURN NULL;
END $$;
CREATE TRIGGER "trg_customer_wallet_common_post" AFTER INSERT ON "customer_wallet_ledger" FOR EACH ROW EXECUTE FUNCTION "trg_customer_wallet_common_post_fn"();
CREATE OR REPLACE FUNCTION "trg_deposit_insurance_claims_currency_money_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."covered_amount" IS NOT DISTINCT FROM NULL OR NEW."covered_amount" <> ROUND(CAST(((COALESCE(NEW."covered_amount", 0)) + CASE WHEN (COALESCE(NEW."covered_amount", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM accounts WHERE account_number = NEW.account_number)), 0) AS INT))) OR (NEW."uninsured_amount" IS NOT DISTINCT FROM NULL OR NEW."uninsured_amount" <> ROUND(CAST(((COALESCE(NEW."uninsured_amount", 0)) + CASE WHEN (COALESCE(NEW."uninsured_amount", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM accounts WHERE account_number = NEW.account_number)), 0) AS INT)))) THEN
        NEW."covered_amount" := ROUND(CAST(((COALESCE(NEW."covered_amount", 0)) + CASE WHEN (COALESCE(NEW."covered_amount", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM accounts WHERE account_number = NEW.account_number)), 0) AS INT));
