CREATE OR REPLACE FUNCTION "trg_dr_custody_instruction_event_sequence_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT EXISTS(SELECT 1 FROM dr_custody_instructions AS i WHERE i.reference_key = NEW.reference_key AND i.status = NEW.event_type) OR NEW.event_sequence <> (SELECT COALESCE(MAX(e.event_sequence), 0) + 1 FROM dr_custody_instruction_events AS e WHERE e.reference_key = NEW.reference_key)) THEN
        RAISE EXCEPTION USING MESSAGE = 'invalid DR custody instruction event sequence', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
