CREATE TRIGGER "trg_dr_custody_instruction_transition" BEFORE UPDATE ON "dr_custody_instructions" FOR EACH ROW WHEN (NOT ((OLD.status = 'requested' AND NEW.status IN ('verified', 'rejected', 'cancelled')) OR (OLD.status = 'verified' AND NEW.status IN ('settled', 'rejected', 'cancelled'))) OR NEW.reference_key <> OLD.reference_key OR NEW.dr_code <> OLD.dr_code OR NEW.user_id <> OLD.user_id OR NEW.movement_type <> OLD.movement_type OR NEW.dr_quantity <> OLD.dr_quantity OR NEW.underlying_quantity <> OLD.underlying_quantity OR NEW.requested_epoch <> OLD.requested_epoch OR NEW.updated_epoch < OLD.updated_epoch OR NEW.fee_bps <> OLD.fee_bps OR NOT NEW.fee_currency IS NOT DISTINCT FROM OLD.fee_currency OR NOT NEW.fee_price IS NOT DISTINCT FROM OLD.fee_price OR (NEW.status = 'settled' AND NEW.settled_epoch IS NULL) OR (NEW.status <> 'settled' AND NOT NEW.settled_epoch IS NULL)) EXECUTE FUNCTION raise_abort('invalid DR custody instruction transition');
CREATE TRIGGER "trg_dr_custody_instructions_no_delete" BEFORE DELETE ON "dr_custody_instructions" FOR EACH ROW EXECUTE FUNCTION raise_abort('DR custody instructions are retained for audit');
