        NEW."reference_value" := ROUND(CAST(((COALESCE(NEW."reference_value", 0)) + CASE WHEN (COALESCE(NEW."reference_value", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM depositary_receipts WHERE dr_code = NEW.dr_code)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
