CREATE OR REPLACE FUNCTION "trg_dr_movements_cost_units_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW."underlying_average_cost_minor_units" IS NOT DISTINCT FROM NULL OR NEW."underlying_average_cost_decimal_places" IS NULL OR NOT NEW."underlying_average_cost_currency" IS NOT DISTINCT FROM COALESCE((SELECT quote_currency FROM company WHERE company_code = (SELECT underlying_code FROM depositary_receipts WHERE dr_code = NEW.dr_code)), BASE_CURRENCY_CODE()) OR NEW."underlying_average_cost_decimal_places" <> COALESCE((SELECT decimal_places FROM currencies WHERE code = COALESCE((SELECT quote_currency FROM company WHERE company_code = (SELECT underlying_code FROM depositary_receipts WHERE dr_code = NEW.dr_code)), BASE_CURRENCY_CODE())), -1) OR NEW."underlying_average_cost_minor_units" <> TRUNC(ROUND(CAST((NEW."underlying_average_cost" * (CASE COALESCE(NEW."underlying_average_cost_decimal_places", 0) WHEN 0 THEN 1 WHEN 1 THEN 10 WHEN 2 THEN 100 WHEN 3 THEN 1000 WHEN 4 THEN 10000 WHEN 5 THEN 100000 WHEN 6 THEN 1000000 END)) AS DECIMAL), CAST(0 AS INT))) OR NEW."holder_underlying_average_cost_minor_units" IS NOT DISTINCT FROM NULL OR NEW."holder_underlying_average_cost_decimal_places" IS NULL OR NOT NEW."holder_underlying_currency" IS NOT DISTINCT FROM COALESCE(NEW.holder_underlying_currency, BASE_CURRENCY_CODE()) OR NEW."holder_underlying_average_cost_decimal_places" <> COALESCE((SELECT decimal_places FROM currencies WHERE code = COALESCE(NEW.holder_underlying_currency, BASE_CURRENCY_CODE())), -1) OR NEW."holder_underlying_average_cost_minor_units" <> TRUNC(ROUND(CAST((NEW."holder_underlying_average_cost" * (CASE COALESCE(NEW."holder_underlying_average_cost_decimal_places", 0) WHEN 0 THEN 1 WHEN 1 THEN 10 WHEN 2 THEN 100 WHEN 3 THEN 1000 WHEN 4 THEN 10000 WHEN 5 THEN 100000 WHEN 6 THEN 1000000 END)) AS DECIMAL), CAST(0 AS INT))) OR NEW."custody_underlying_average_cost_minor_units" IS NOT DISTINCT FROM NULL OR NEW."custody_underlying_average_cost_decimal_places" IS NULL OR NOT NEW."custody_underlying_currency" IS NOT DISTINCT FROM COALESCE(NEW.custody_underlying_currency, BASE_CURRENCY_CODE()) OR NEW."custody_underlying_average_cost_decimal_places" <> COALESCE((SELECT decimal_places FROM currencies WHERE code = COALESCE(NEW.custody_underlying_currency, BASE_CURRENCY_CODE())), -1) OR NEW."custody_underlying_average_cost_minor_units" <> TRUNC(ROUND(CAST((NEW."custody_underlying_average_cost" * (CASE COALESCE(NEW."custody_underlying_average_cost_decimal_places", 0) WHEN 0 THEN 1 WHEN 1 THEN 10 WHEN 2 THEN 100 WHEN 3 THEN 1000 WHEN 4 THEN 10000 WHEN 5 THEN 100000 WHEN 6 THEN 1000000 END)) AS DECIMAL), CAST(0 AS INT)))) THEN
        RAISE EXCEPTION USING MESSAGE = 'DR movement cost minor units are missing or inconsistent', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
