CREATE OR REPLACE FUNCTION "trg_dr_requires_program_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.type = 'depositary_receipt' AND NOT EXISTS(SELECT 1 FROM depositary_receipts WHERE dr_code = NEW.code)) THEN
        RAISE EXCEPTION USING MESSAGE = 'DR asset requires a depositary receipt program', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
