CREATE OR REPLACE FUNCTION "trg_dr_voting_delegations_revoke_only_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT (OLD.status = 'active' AND NEW.status = 'revoked' AND OLD.revoked_epoch IS NULL AND NOT NEW.revoked_epoch IS NULL AND OLD.delegation_id = NEW.delegation_id AND OLD.dr_code = NEW.dr_code AND OLD.owner_user_id = NEW.owner_user_id AND OLD.proxy_user_id = NEW.proxy_user_id AND OLD.dr_quantity = NEW.dr_quantity AND OLD.created_epoch = NEW.created_epoch AND EXISTS(SELECT 1 FROM dr_voting_delegation_events AS e WHERE e.delegation_id = OLD.delegation_id AND e.event_type = 'revoked' AND e.actor_user_id = OLD.owner_user_id AND e.recorded_epoch = NEW.revoked_epoch))) THEN
        RAISE EXCEPTION USING MESSAGE = 'DR voting delegation changes require an audit event', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
