    IF (OLD.product_type = 'els' AND EXISTS(SELECT 1 FROM els_subscriptions AS s WHERE s.product_code = OLD.product_code) AND (NOT NEW.face_value IS NOT DISTINCT FROM OLD.face_value OR NOT NEW.annual_rate IS NOT DISTINCT FROM OLD.annual_rate OR NOT NEW.maturity_days IS NOT DISTINCT FROM OLD.maturity_days OR NOT NEW.total_supply IS NOT DISTINCT FROM OLD.total_supply OR NOT NEW.issuer_code IS NOT DISTINCT FROM OLD.issuer_code OR NOT NEW.quote_currency IS NOT DISTINCT FROM OLD.quote_currency)) THEN
        RAISE EXCEPTION USING MESSAGE = '청약 이후 ELS 발행조건을 변경할 수 없습니다.', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
