CREATE OR REPLACE FUNCTION "trg_financial_institution_id_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.institution_id IS NULL) THEN
        NEW."institution_id" := CASE WHEN NEW.issuer = 'Inazina' AND NOT EXISTS(SELECT 1 FROM financial_institutions WHERE institution_id = 'INAZINA') THEN 'INAZINA' ELSE 'BNK' || LPAD(CAST(ABS(CAST(FLOOR(RANDOM() * 9007199254740991) AS BIGINT)) % 1000000 AS TEXT), 6, '0') END;
    END IF;
    RETURN NEW;
END $$;
