CREATE OR REPLACE FUNCTION "trg_financial_institutions_currency_money_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."equity_capital" IS NOT DISTINCT FROM NULL OR NEW."equity_capital" <> ROUND(CAST(((COALESCE(NEW."equity_capital", 0)) + CASE WHEN (COALESCE(NEW."equity_capital", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT))) OR (NEW."retained_earnings" IS NOT DISTINCT FROM NULL OR NEW."retained_earnings" <> ROUND(CAST(((COALESCE(NEW."retained_earnings", 0)) + CASE WHEN (COALESCE(NEW."retained_earnings", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT))) OR (NEW."deposit_insurance_limit" IS NOT DISTINCT FROM NULL OR NEW."deposit_insurance_limit" <> ROUND(CAST(((COALESCE(NEW."deposit_insurance_limit", 0)) + CASE WHEN (COALESCE(NEW."deposit_insurance_limit", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT)))) THEN
        NEW."equity_capital" := ROUND(CAST(((COALESCE(NEW."equity_capital", 0)) + CASE WHEN (COALESCE(NEW."equity_capital", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT));
        NEW."retained_earnings" := ROUND(CAST(((COALESCE(NEW."retained_earnings", 0)) + CASE WHEN (COALESCE(NEW."retained_earnings", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT));
        NEW."deposit_insurance_limit" := ROUND(CAST(((COALESCE(NEW."deposit_insurance_limit", 0)) + CASE WHEN (COALESCE(NEW."deposit_insurance_limit", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_financial_institutions_currency_money_insert" BEFORE INSERT ON "financial_institutions" FOR EACH ROW EXECUTE FUNCTION "trg_financial_institutions_currency_money_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_financial_institutions_currency_money_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."equity_capital" IS NOT DISTINCT FROM NULL OR NEW."equity_capital" <> ROUND(CAST(((COALESCE(NEW."equity_capital", 0)) + CASE WHEN (COALESCE(NEW."equity_capital", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT))) OR (NEW."retained_earnings" IS NOT DISTINCT FROM NULL OR NEW."retained_earnings" <> ROUND(CAST(((COALESCE(NEW."retained_earnings", 0)) + CASE WHEN (COALESCE(NEW."retained_earnings", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT))) OR (NEW."deposit_insurance_limit" IS NOT DISTINCT FROM NULL OR NEW."deposit_insurance_limit" <> ROUND(CAST(((COALESCE(NEW."deposit_insurance_limit", 0)) + CASE WHEN (COALESCE(NEW."deposit_insurance_limit", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT)))) THEN
        NEW."equity_capital" := ROUND(CAST(((COALESCE(NEW."equity_capital", 0)) + CASE WHEN (COALESCE(NEW."equity_capital", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT));
        NEW."retained_earnings" := ROUND(CAST(((COALESCE(NEW."retained_earnings", 0)) + CASE WHEN (COALESCE(NEW."retained_earnings", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT));
        NEW."deposit_insurance_limit" := ROUND(CAST(((COALESCE(NEW."deposit_insurance_limit", 0)) + CASE WHEN (COALESCE(NEW."deposit_insurance_limit", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT c.currency_code FROM country_currencies AS c WHERE c.nationality = NEW.nationality)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_financial_institutions_currency_money_update" BEFORE UPDATE OF "equity_capital", "retained_earnings", "deposit_insurance_limit" ON "financial_institutions" FOR EACH ROW EXECUTE FUNCTION "trg_financial_institutions_currency_money_update_fn"();
CREATE OR REPLACE FUNCTION "trg_fund_accounts_currency_money_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."cash" IS NOT DISTINCT FROM NULL OR NEW."cash" <> ROUND(CAST(((COALESCE(NEW."cash", 0)) + CASE WHEN (COALESCE(NEW."cash", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM investment WHERE product_code = NEW.product_code)), 0) AS INT))) OR (NEW."initial_nav" IS NOT DISTINCT FROM NULL OR NEW."initial_nav" <> ROUND(CAST(((COALESCE(NEW."initial_nav", 0)) + CASE WHEN (COALESCE(NEW."initial_nav", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM investment WHERE product_code = NEW.product_code)), 0) AS INT)))) THEN
        NEW."cash" := ROUND(CAST(((COALESCE(NEW."cash", 0)) + CASE WHEN (COALESCE(NEW."cash", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM investment WHERE product_code = NEW.product_code)), 0) AS INT));
        NEW."initial_nav" := ROUND(CAST(((COALESCE(NEW."initial_nav", 0)) + CASE WHEN (COALESCE(NEW."initial_nav", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM investment WHERE product_code = NEW.product_code)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_fund_accounts_currency_money_insert" BEFORE INSERT ON "fund_accounts" FOR EACH ROW EXECUTE FUNCTION "trg_fund_accounts_currency_money_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_fund_accounts_currency_money_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."cash" IS NOT DISTINCT FROM NULL OR NEW."cash" <> ROUND(CAST(((COALESCE(NEW."cash", 0)) + CASE WHEN (COALESCE(NEW."cash", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM investment WHERE product_code = NEW.product_code)), 0) AS INT))) OR (NEW."initial_nav" IS NOT DISTINCT FROM NULL OR NEW."initial_nav" <> ROUND(CAST(((COALESCE(NEW."initial_nav", 0)) + CASE WHEN (COALESCE(NEW."initial_nav", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM investment WHERE product_code = NEW.product_code)), 0) AS INT)))) THEN
        NEW."cash" := ROUND(CAST(((COALESCE(NEW."cash", 0)) + CASE WHEN (COALESCE(NEW."cash", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM investment WHERE product_code = NEW.product_code)), 0) AS INT));
        NEW."initial_nav" := ROUND(CAST(((COALESCE(NEW."initial_nav", 0)) + CASE WHEN (COALESCE(NEW."initial_nav", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM investment WHERE product_code = NEW.product_code)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_fund_accounts_currency_money_update" BEFORE UPDATE OF "cash", "initial_nav" ON "fund_accounts" FOR EACH ROW EXECUTE FUNCTION "trg_fund_accounts_currency_money_update_fn"();
CREATE OR REPLACE FUNCTION "trg_fund_cash_common_post_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO journal_entries (ledger_scope, entity_type, entity_id, source_key, currency_code, decimal_places, recorded_epoch, description) VALUES ('fund', 'fund_cash', NEW.product_code, 'fund-cash:' || NEW.entry_id, NEW.currency_code, NEW.decimal_places, NEW.recorded_epoch, NEW.event);
    INSERT INTO journal_lines (entry_id, account_code, debit_units, credit_units) SELECT entry_id, 'fund_cash', CASE WHEN NEW.amount_minor_units > 0 THEN NEW.amount_minor_units ELSE 0 END, CASE WHEN NEW.amount_minor_units < 0 THEN (0 - NEW.amount_minor_units) ELSE 0 END FROM journal_entries WHERE ledger_scope = 'fund' AND entity_type = 'fund_cash' AND entity_id = NEW.product_code AND source_key = 'fund-cash:' || NEW.entry_id;
    INSERT INTO journal_lines (entry_id, account_code, debit_units, credit_units) SELECT entry_id, 'fund_cash_clearing', CASE WHEN NEW.amount_minor_units < 0 THEN (0 - NEW.amount_minor_units) ELSE 0 END, CASE WHEN NEW.amount_minor_units > 0 THEN NEW.amount_minor_units ELSE 0 END FROM journal_entries WHERE ledger_scope = 'fund' AND entity_type = 'fund_cash' AND entity_id = NEW.product_code AND source_key = 'fund-cash:' || NEW.entry_id;
    RETURN NULL;
END $$;
CREATE TRIGGER "trg_fund_cash_common_post" AFTER INSERT ON "fund_cash_ledger" FOR EACH ROW EXECUTE FUNCTION "trg_fund_cash_common_post_fn"();
CREATE OR REPLACE FUNCTION "trg_fund_cash_ledger_currency_money_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."amount" IS NOT DISTINCT FROM NULL OR NEW."amount" <> ROUND(CAST(((COALESCE(NEW."amount", 0)) + CASE WHEN (COALESCE(NEW."amount", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT))) OR (NEW."balance" IS NOT DISTINCT FROM NULL OR NEW."balance" <> ROUND(CAST(((COALESCE(NEW."balance", 0)) + CASE WHEN (COALESCE(NEW."balance", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT))) OR (NEW."amount_minor_units" IS NOT DISTINCT FROM NULL OR NEW."amount_minor_units" <> ROUND(CAST(((COALESCE(NEW."amount_minor_units", 0)) + CASE WHEN (COALESCE(NEW."amount_minor_units", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT))) OR (NEW."balance_minor_units" IS NOT DISTINCT FROM NULL OR NEW."balance_minor_units" <> ROUND(CAST(((COALESCE(NEW."balance_minor_units", 0)) + CASE WHEN (COALESCE(NEW."balance_minor_units", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT)))) THEN
        NEW."amount" := ROUND(CAST(((COALESCE(NEW."amount", 0)) + CASE WHEN (COALESCE(NEW."amount", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
        NEW."balance" := ROUND(CAST(((COALESCE(NEW."balance", 0)) + CASE WHEN (COALESCE(NEW."balance", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
        NEW."amount_minor_units" := ROUND(CAST(((COALESCE(NEW."amount_minor_units", 0)) + CASE WHEN (COALESCE(NEW."amount_minor_units", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
        NEW."balance_minor_units" := ROUND(CAST(((COALESCE(NEW."balance_minor_units", 0)) + CASE WHEN (COALESCE(NEW."balance_minor_units", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_fund_cash_ledger_currency_money_insert" BEFORE INSERT ON "fund_cash_ledger" FOR EACH ROW EXECUTE FUNCTION "trg_fund_cash_ledger_currency_money_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_fund_cash_ledger_currency_money_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."amount" IS NOT DISTINCT FROM NULL OR NEW."amount" <> ROUND(CAST(((COALESCE(NEW."amount", 0)) + CASE WHEN (COALESCE(NEW."amount", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT))) OR (NEW."balance" IS NOT DISTINCT FROM NULL OR NEW."balance" <> ROUND(CAST(((COALESCE(NEW."balance", 0)) + CASE WHEN (COALESCE(NEW."balance", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT))) OR (NEW."amount_minor_units" IS NOT DISTINCT FROM NULL OR NEW."amount_minor_units" <> ROUND(CAST(((COALESCE(NEW."amount_minor_units", 0)) + CASE WHEN (COALESCE(NEW."amount_minor_units", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT))) OR (NEW."balance_minor_units" IS NOT DISTINCT FROM NULL OR NEW."balance_minor_units" <> ROUND(CAST(((COALESCE(NEW."balance_minor_units", 0)) + CASE WHEN (COALESCE(NEW."balance_minor_units", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT)))) THEN
        NEW."amount" := ROUND(CAST(((COALESCE(NEW."amount", 0)) + CASE WHEN (COALESCE(NEW."amount", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
        NEW."balance" := ROUND(CAST(((COALESCE(NEW."balance", 0)) + CASE WHEN (COALESCE(NEW."balance", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
        NEW."amount_minor_units" := ROUND(CAST(((COALESCE(NEW."amount_minor_units", 0)) + CASE WHEN (COALESCE(NEW."amount_minor_units", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
        NEW."balance_minor_units" := ROUND(CAST(((COALESCE(NEW."balance_minor_units", 0)) + CASE WHEN (COALESCE(NEW."balance_minor_units", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_fund_cash_ledger_currency_money_update" BEFORE UPDATE OF "amount", "balance", "amount_minor_units", "balance_minor_units" ON "fund_cash_ledger" FOR EACH ROW EXECUTE FUNCTION "trg_fund_cash_ledger_currency_money_update_fn"();
CREATE OR REPLACE FUNCTION "trg_institution_equity_units_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.equity_capital_minor_units IS NOT DISTINCT FROM NULL) THEN
        NEW."equity_capital_currency_code" := COALESCE((SELECT currency_code FROM country_currencies WHERE nationality = NEW.nationality), BASE_CURRENCY_CODE());
        NEW."equity_capital_decimal_places" := COALESCE((SELECT decimal_places FROM currencies WHERE code = COALESCE((SELECT currency_code FROM country_currencies WHERE nationality = NEW.nationality), BASE_CURRENCY_CODE())), 0);
        NEW."equity_capital_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.equity_capital, 0) * CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = COALESCE((SELECT currency_code FROM country_currencies WHERE nationality = NEW.nationality), BASE_CURRENCY_CODE())), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) AS DECIMAL), CAST(0 AS INT)));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_institution_equity_units_insert" BEFORE INSERT ON "financial_institutions" FOR EACH ROW EXECUTE FUNCTION "trg_institution_equity_units_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_institution_equity_units_legacy_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.equity_capital IS NOT DISTINCT FROM OLD.equity_capital) THEN
        NEW."equity_capital_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.equity_capital, 0) * CASE NEW.equity_capital_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) AS DECIMAL), CAST(0 AS INT)));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_institution_equity_units_legacy_update" BEFORE UPDATE OF "equity_capital" ON "financial_institutions" FOR EACH ROW EXECUTE FUNCTION "trg_institution_equity_units_legacy_update_fn"();
CREATE OR REPLACE FUNCTION "trg_institution_equity_units_mirror_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.equity_capital_minor_units IS NOT DISTINCT FROM OLD.equity_capital_minor_units AND NOT NEW.equity_capital_minor_units IS NOT DISTINCT FROM NULL) THEN
        NEW."equity_capital" := CASE WHEN (NEW.equity_capital_minor_units * 1.0) = TRUNC((NEW.equity_capital_minor_units * 1.0)) AND CASE NEW.equity_capital_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END = TRUNC(CASE NEW.equity_capital_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) THEN TRUNC((NEW.equity_capital_minor_units * 1.0) / CASE NEW.equity_capital_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) ELSE (NEW.equity_capital_minor_units * 1.0) / CASE NEW.equity_capital_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END END;
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_institution_equity_units_mirror" BEFORE UPDATE OF "equity_capital_minor_units" ON "financial_institutions" FOR EACH ROW EXECUTE FUNCTION "trg_institution_equity_units_mirror_fn"();
CREATE OR REPLACE FUNCTION "trg_institution_retained_units_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.retained_earnings_minor_units IS NOT DISTINCT FROM NULL) THEN
        NEW."retained_earnings_currency_code" := COALESCE((SELECT currency_code FROM country_currencies WHERE nationality = NEW.nationality), BASE_CURRENCY_CODE());
        NEW."retained_earnings_decimal_places" := COALESCE((SELECT decimal_places FROM currencies WHERE code = COALESCE((SELECT currency_code FROM country_currencies WHERE nationality = NEW.nationality), BASE_CURRENCY_CODE())), 0);
        NEW."retained_earnings_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.retained_earnings, 0) * CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = COALESCE((SELECT currency_code FROM country_currencies WHERE nationality = NEW.nationality), BASE_CURRENCY_CODE())), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) AS DECIMAL), CAST(0 AS INT)));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_institution_retained_units_insert" BEFORE INSERT ON "financial_institutions" FOR EACH ROW EXECUTE FUNCTION "trg_institution_retained_units_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_institution_retained_units_legacy_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.retained_earnings IS NOT DISTINCT FROM OLD.retained_earnings) THEN
        NEW."retained_earnings_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.retained_earnings, 0) * CASE NEW.retained_earnings_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) AS DECIMAL), CAST(0 AS INT)));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_institution_retained_units_legacy_update" BEFORE UPDATE OF "retained_earnings" ON "financial_institutions" FOR EACH ROW EXECUTE FUNCTION "trg_institution_retained_units_legacy_update_fn"();
CREATE OR REPLACE FUNCTION "trg_institution_retained_units_mirror_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.retained_earnings_minor_units IS NOT DISTINCT FROM OLD.retained_earnings_minor_units) THEN
        NEW."retained_earnings" := CASE WHEN (NEW.retained_earnings_minor_units * 1.0) = TRUNC((NEW.retained_earnings_minor_units * 1.0)) AND CASE NEW.retained_earnings_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END = TRUNC(CASE NEW.retained_earnings_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) THEN TRUNC((NEW.retained_earnings_minor_units * 1.0) / CASE NEW.retained_earnings_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END) ELSE (NEW.retained_earnings_minor_units * 1.0) / CASE NEW.retained_earnings_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END END;
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_institution_retained_units_mirror" BEFORE UPDATE OF "retained_earnings_minor_units" ON "financial_institutions" FOR EACH ROW EXECUTE FUNCTION "trg_institution_retained_units_mirror_fn"();
CREATE OR REPLACE FUNCTION "trg_insurance_payout_minor_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW.payout_amount IS NOT DISTINCT FROM NULL AND (NOT NEW.payout_amount_minor_units IS NOT DISTINCT FROM NULL OR NOT NEW.payout_decimal_places IS NULL)) OR (NOT NEW.payout_amount IS NOT DISTINCT FROM NULL AND NOT NEW.payout_currency IS NULL AND EXISTS(SELECT 1 FROM currencies WHERE code = NEW.payout_currency) AND (NEW.payout_amount_minor_units IS NOT DISTINCT FROM NULL OR NEW.payout_decimal_places IS NULL OR NEW.payout_decimal_places <> COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.payout_currency), -1) OR NEW.payout_amount_minor_units <> TRUNC(ROUND(CAST((NEW.payout_amount * CASE NEW.payout_decimal_places WHEN 0 THEN 1 WHEN 1 THEN 10 WHEN 2 THEN 100 END) AS DECIMAL), CAST(0 AS INT)))))) THEN
        RAISE EXCEPTION USING MESSAGE = 'insurance payout minor units are missing or inconsistent', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_insurance_payout_minor_insert" BEFORE INSERT ON "deposit_insurance_claims" FOR EACH ROW EXECUTE FUNCTION "trg_insurance_payout_minor_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_insurance_payout_pair_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW.payout_currency IS NULL) <> (NEW.payout_amount IS NOT DISTINCT FROM NULL) OR (NOT NEW.payout_currency IS NULL AND NOT EXISTS(SELECT 1 FROM currencies WHERE code = NEW.payout_currency))) THEN
        RAISE EXCEPTION USING MESSAGE = 'insurance payout currency and amount must be paired and use a known currency', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_insurance_payout_pair_insert" BEFORE INSERT ON "deposit_insurance_claims" FOR EACH ROW EXECUTE FUNCTION "trg_insurance_payout_pair_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_insurance_payout_precision_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.payout_amount IS NOT DISTINCT FROM NULL AND NOT NEW.payout_currency IS NULL AND NEW.payout_amount <> ROUND(CAST((NEW.payout_amount + CASE WHEN NEW.payout_amount >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.payout_currency), 0) AS INT))) THEN
        RAISE EXCEPTION USING MESSAGE = 'insurance payout amount exceeds currency precision', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_insurance_payout_precision_insert" BEFORE INSERT ON "deposit_insurance_claims" FOR EACH ROW EXECUTE FUNCTION "trg_insurance_payout_precision_insert_fn"();
