CREATE OR REPLACE FUNCTION "trg_liability_floating_reprice_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW.kind = 'loan') AND (NEW.rate_type = 'floating' AND NEW.benchmark_key = 'policy')) THEN
        NEW."interest_rate" := LEAST((SELECT legal_max_rate FROM country_currencies WHERE nationality = NEW.rate_nationality), COALESCE(NEW.rate_cap, 100), GREATEST(NEW.rate_floor, (SELECT base_rate FROM country_currencies WHERE nationality = NEW.rate_nationality) + NEW.base_rate_spread + NEW.maturity_spread + NEW.promotional_adjustment + COALESCE((SELECT funding_spread + operating_cost_spread + liquidity_spread + target_margin + competition_adjustment FROM financial_institutions WHERE issuer = NEW.issuer), 1.7)));
    END IF;
    RETURN NEW;
END $$;
