CREATE OR REPLACE FUNCTION "trg_liability_floating_terms_validate_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW.kind = 'loan') AND (NEW.rate_type = 'floating' AND (NEW.rate_nationality IS NULL OR NOT EXISTS(SELECT 1 FROM country_currencies AS c WHERE c.nationality = NEW.rate_nationality AND c.currency_code = NEW.quote_currency) OR NEW.rate_floor < 0 OR NEW.rate_floor > 100 OR NOT NEW.rate_cap IS NULL AND (NEW.rate_cap < NEW.rate_floor OR NEW.rate_cap > 100) OR NOT NEW.benchmark_key IN ('policy', 'funding', 'bank_bond', 'treasury') OR NEW.benchmark_key <> 'policy' AND NEW.benchmark_tenor_days <= 0 OR NEW.repricing_lag_seconds < 0 OR NEW.repricing_cycle_seconds <= 0 OR NEW.interest_cycle <= 0 OR NEW.repricing_cycle_seconds < NEW.interest_cycle OR ABS(NEW.repricing_cycle_seconds / NULLIF(NEW.interest_cycle, 0) - ROUND(CAST(NEW.repricing_cycle_seconds / NULLIF(NEW.interest_cycle, 0) AS DECIMAL))) > 0.000000001))) THEN
        RAISE EXCEPTION USING MESSAGE = '변동금리 국적·하한·상한·재산정주기 설정을 확인해주세요.', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
