CREATE OR REPLACE FUNCTION "trg_liability_legal_max_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW.kind = 'loan') AND ((NEW.interest_rate IS NULL OR NEW.interest_rate < 0 OR NEW.interest_rate > COALESCE((SELECT c.legal_max_rate FROM country_currencies AS c WHERE c.nationality = NEW.rate_nationality), (SELECT MIN(c.legal_max_rate) FROM country_currencies AS c WHERE c.currency_code = NEW.quote_currency), CAST((SELECT value FROM settings WHERE key = 'legal_max_rate') AS DOUBLE PRECISION), 20)))) THEN
        RAISE EXCEPTION USING MESSAGE = '상품 이율이 해당 국적의 법정최고이자를 초과합니다.', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_liability_legal_max_insert" BEFORE INSERT ON "bank_products" FOR EACH ROW EXECUTE FUNCTION "trg_liability_legal_max_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_liability_legal_max_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
