)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM loans WHERE loan_id = NEW.loan_id)), 0) AS INT)))) THEN
        NEW."average_cost" := ROUND(CAST(((COALESCE(NEW."average_cost", 0)) + CASE WHEN (COALESCE(NEW."average_cost", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM loans WHERE loan_id = NEW.loan_id)), 0) AS INT));
        NEW."last_price" := ROUND(CAST(((COALESCE(NEW."last_price", 0)) + CASE WHEN (COALESCE(NEW."last_price", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM loans WHERE loan_id = NEW.loan_id)), 0) AS INT));
        NEW."last_value" := ROUND(CAST(((COALESCE(NEW."last_value", 0)) + CASE WHEN (COALESCE(NEW."last_value", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM loans WHERE loan_id = NEW.loan_id)), 0) AS INT));
        NEW."liquidation_price" := ROUND(CAST(((COALESCE(NEW."liquidation_price", 0)) + CASE WHEN (COALESCE(NEW."liquidation_price", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM loans WHERE loan_id = NEW.loan_id)), 0) AS INT));
        NEW."liquidation_cost" := ROUND(CAST(((COALESCE(NEW."liquidation_cost", 0)) + CASE WHEN (COALESCE(NEW."liquidation_cost", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM loans WHERE loan_id = NEW.loan_id)), 0) AS INT));
        NEW."liquidation_proceeds" := ROUND(CAST(((COALESCE(NEW."liquidation_proceeds", 0)) + CASE WHEN (COALESCE(NEW."liquidation_proceeds", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM loans WHERE loan_id = NEW.loan_id)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
