    NEW."fee_paid_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.fee_paid, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = (SELECT quote_currency FROM loans WHERE loan_id = NEW.loan_id)), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
