CREATE OR REPLACE FUNCTION "trg_loans_legal_max_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.contract_rate IS NULL AND (NEW.contract_rate < 0 OR NEW.contract_rate > COALESCE((SELECT c.legal_max_rate FROM country_currencies AS c WHERE c.nationality = NEW.rate_nationality), (SELECT MIN(c.legal_max_rate) FROM (SELECT * FROM bank_products WHERE kind = 'loan') AS p JOIN country_currencies AS c ON c.currency_code = p.quote_currency WHERE p.product_code = NEW.product_code), CAST((SELECT value FROM settings WHERE key = 'legal_max_rate') AS DOUBLE PRECISION), 20))) THEN
        RAISE EXCEPTION USING MESSAGE = '대출 계약 이율이 해당 국적의 법정최고이자를 초과합니다.', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
