CREATE OR REPLACE FUNCTION "trg_loans_outstanding_balance_snap_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.outstanding_balance IS NOT DISTINCT FROM NULL AND NEW.outstanding_balance <> ROUND(CAST(NEW.outstanding_balance AS DECIMAL), CAST((SELECT COALESCE(MAX(decimal_places), 0) FROM currencies WHERE code = COALESCE(NEW.quote_currency, BASE_CURRENCY_CODE())) AS INT))) THEN
        UPDATE loans SET outstanding_balance = ROUND(CAST(NEW.outstanding_balance AS DECIMAL), CAST((SELECT COALESCE(MAX(decimal_places), 0) FROM currencies WHERE code = COALESCE(NEW.quote_currency, BASE_CURRENCY_CODE())) AS INT)) WHERE rowid = NEW.rowid;
    END IF;
    RETURN NULL;
END $$;
