CREATE OR REPLACE FUNCTION "trg_market_assets_currency_money_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."price" IS NOT DISTINCT FROM NULL OR NEW."price" <> ROUND(CAST(((COALESCE(NEW."price", 0)) + CASE WHEN (COALESCE(NEW."price", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT))) OR (NEW."dividend_per_share" IS NOT DISTINCT FROM NULL OR NEW."dividend_per_share" <> ROUND(CAST(((COALESCE(NEW."dividend_per_share", 0)) + CASE WHEN (COALESCE(NEW."dividend_per_share", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT)))) THEN
        NEW."price" := ROUND(CAST(((COALESCE(NEW."price", 0)) + CASE WHEN (COALESCE(NEW."price", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
        NEW."dividend_per_share" := ROUND(CAST(((COALESCE(NEW."dividend_per_share", 0)) + CASE WHEN (COALESCE(NEW."dividend_per_share", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_market_assets_currency_money_insert" BEFORE INSERT ON "market_assets" FOR EACH ROW EXECUTE FUNCTION "trg_market_assets_currency_money_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_market_assets_currency_money_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW."price" IS NOT DISTINCT FROM NULL OR NEW."price" <> ROUND(CAST(((COALESCE(NEW."price", 0)) + CASE WHEN (COALESCE(NEW."price", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT))) OR (NEW."dividend_per_share" IS NOT DISTINCT FROM NULL OR NEW."dividend_per_share" <> ROUND(CAST(((COALESCE(NEW."dividend_per_share", 0)) + CASE WHEN (COALESCE(NEW."dividend_per_share", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT)))) THEN
        NEW."price" := ROUND(CAST(((COALESCE(NEW."price", 0)) + CASE WHEN (COALESCE(NEW."price", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
        NEW."dividend_per_share" := ROUND(CAST(((COALESCE(NEW."dividend_per_share", 0)) + CASE WHEN (COALESCE(NEW."dividend_per_share", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
