CREATE OR REPLACE FUNCTION "trg_market_assets_price_minor_authority_legacy_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW."price_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.price, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
    RETURN NEW;
END $$;
