CREATE OR REPLACE FUNCTION "trg_market_assets_price_minor_authority_minor_to_legacy_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW."price" <> (CAST(NEW.price_minor_units AS DECIMAL) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END))) THEN
        NEW."price" := (CAST(NEW.price_minor_units AS DECIMAL) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.quote_currency)), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END));
