CREATE OR REPLACE FUNCTION "trg_market_curve_history_event_delete_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    INSERT INTO market_rate_curve_history_events (operation, nationality, benchmark_key, tenor_days, before_rate, after_rate, before_epoch, after_epoch, before_actor, after_actor, recorded_epoch) VALUES ('delete', COALESCE(NULL, OLD.nationality), COALESCE(NULL, OLD.benchmark_key), COALESCE(NULL, OLD.tenor_days), OLD.annual_rate, NULL, OLD.effective_epoch, NULL, OLD.changed_by, NULL, ((EXTRACT(EPOCH FROM CURRENT_TIMESTAMP) / 86400.0 + 2440587.5) - 2440587.5) * 86400.0);
    RETURN NULL;
END $$;
