BEGIN
    INSERT INTO market_rate_curve_history_events (operation, nationality, benchmark_key, tenor_days, before_rate, after_rate, before_epoch, after_epoch, before_actor, after_actor, recorded_epoch) VALUES ('insert', COALESCE(NEW.nationality, NULL), COALESCE(NEW.benchmark_key, NULL), COALESCE(NEW.tenor_days, NULL), NULL, NEW.annual_rate, NULL, NEW.effective_epoch, NULL, NEW.changed_by, ((EXTRACT(EPOCH FROM CURRENT_TIMESTAMP) / 86400.0 + 2440587.5) - 2440587.5) * 86400.0);
    RETURN NULL;
END $$;
