CREATE OR REPLACE FUNCTION "trg_market_curve_history_event_replace_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (EXISTS(SELECT 1 FROM market_rate_curve_history WHERE nationality = NEW.nationality AND benchmark_key = NEW.benchmark_key AND tenor_days = NEW.tenor_days AND effective_epoch = NEW.effective_epoch)) THEN
        INSERT INTO market_rate_curve_history_events (operation, nationality, benchmark_key, tenor_days, before_rate, after_rate, before_epoch, after_epoch, before_actor, after_actor, recorded_epoch) SELECT 'replace', old.nationality, old.benchmark_key, old.tenor_days, old.annual_rate, NEW.annual_rate, old.effective_epoch, NEW.effective_epoch, old.changed_by, NEW.changed_by, ((EXTRACT(EPOCH FROM CURRENT_TIMESTAMP) / 86400.0 + 2440587.5) - 2440587.5) * 86400.0 FROM market_rate_curve_history AS old WHERE old.nationality = NEW.nationality AND old.benchmark_key = NEW.benchmark_key AND old.tenor_days = NEW.tenor_days AND old.effective_epoch = NEW.effective_epoch;
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_market_curve_history_event_replace" BEFORE INSERT ON "market_rate_curve_history" FOR EACH ROW EXECUTE FUNCTION "trg_market_curve_history_event_replace_fn"();
