BEGIN
    INSERT INTO market_rate_curve_history_events (operation, nationality, benchmark_key, tenor_days, before_rate, after_rate, before_epoch, after_epoch, before_actor, after_actor, recorded_epoch) VALUES ('update', COALESCE(NEW.nationality, OLD.nationality), COALESCE(NEW.benchmark_key, OLD.benchmark_key), COALESCE(NEW.tenor_days, OLD.tenor_days), OLD.annual_rate, NEW.annual_rate, OLD.effective_epoch, NEW.effective_epoch, OLD.changed_by, NEW.changed_by, ((EXTRACT(EPOCH FROM CURRENT_TIMESTAMP) / 86400.0 + 2440587.5) - 2440587.5) * 86400.0);
