CREATE OR REPLACE FUNCTION "trg_market_curve_product_reprice_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT NEW.annual_rate IS NOT DISTINCT FROM OLD.annual_rate) THEN
        UPDATE bank_products SET interest_rate = LEAST(COALESCE(rate_cap, 100), GREATEST(CASE WHEN negative_rate_allowed = 1 THEN -100 ELSE rate_floor END, NEW.annual_rate + COALESCE((SELECT adjustment FROM market_rate_pressure AS m WHERE m.nationality = NEW.nationality AND m.benchmark_key = NEW.benchmark_key), 0) + base_rate_spread + maturity_spread + promotional_adjustment + COALESCE((SELECT competition_adjustment FROM financial_institutions AS f WHERE f.issuer = saving.issuer), 0))) WHERE (rate_type = 'floating' AND rate_nationality = NEW.nationality AND benchmark_key = NEW.benchmark_key AND benchmark_tenor_days = NEW.tenor_days) AND saving.kind = 'deposit';
        UPDATE bank_products SET interest_rate = LEAST((SELECT legal_max_rate FROM country_currencies WHERE nationality = NEW.nationality), COALESCE(rate_cap, 100), GREATEST(rate_floor, NEW.annual_rate + COALESCE((SELECT adjustment FROM market_rate_pressure AS m WHERE m.nationality = NEW.nationality AND m.benchmark_key = NEW.benchmark_key), 0) + base_rate_spread + maturity_spread + promotional_adjustment + COALESCE((SELECT funding_spread + operating_cost_spread + liquidity_spread + target_margin + competition_adjustment FROM financial_institutions AS f WHERE f.issuer = liability.issuer), 1.7))) WHERE (rate_type = 'floating' AND rate_nationality = NEW.nationality AND benchmark_key = NEW.benchmark_key AND benchmark_tenor_days = NEW.tenor_days) AND liability.kind = 'loan';
    END IF;
    RETURN NULL;
END $$;
CREATE TRIGGER "trg_market_curve_product_reprice" AFTER UPDATE OF "annual_rate" ON "market_rate_curve" FOR EACH ROW EXECUTE FUNCTION "trg_market_curve_product_reprice_fn"();
