CREATE OR REPLACE FUNCTION "trg_saving_floating_reprice_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW.kind = 'deposit') AND (NEW.rate_type = 'floating' AND NEW.benchmark_key = 'policy')) THEN
        NEW."interest_rate" := LEAST(COALESCE(NEW.rate_cap, 100), GREATEST(NEW.rate_floor, (SELECT base_rate FROM country_currencies WHERE nationality = NEW.rate_nationality) + NEW.base_rate_spread + NEW.maturity_spread + NEW.promotional_adjustment + COALESCE((SELECT competition_adjustment FROM financial_institutions WHERE issuer = NEW.issuer), 0)));
    END IF;
    RETURN NEW;
END $$;
