CREATE OR REPLACE FUNCTION "trg_saving_institution_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF ((NEW.kind = 'deposit') AND (NOT NEW.issuer IS NULL AND TRIM(NEW.issuer) <> '')) THEN
        INSERT INTO financial_institutions (issuer, nationality) VALUES (NEW.issuer, COALESCE(NEW.rate_nationality, (SELECT MIN(c.nationality) FROM country_currencies AS c WHERE c.currency_code = NEW.quote_currency), '낙원')) ON CONFLICT DO NOTHING;
    END IF;
