CREATE OR REPLACE FUNCTION "trg_settings_gamble_validate_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.key IN ('gamble_chance', 'gamble_return')) THEN
        IF (CASE WHEN PG_INPUT_IS_VALID(NEW.value, 'json') THEN 1 ELSE 0 END = 0) THEN
            RAISE EXCEPTION USING MESSAGE = 'Gamble setting must be numeric', ERRCODE = 'check_violation';
        END IF;
        IF (NOT CASE JSONB_TYPEOF(CAST(NEW.value AS JSONB)) WHEN 'number' THEN CASE WHEN NEW.value ~ '^-?[0-9]+$' THEN 'integer' ELSE 'real' END WHEN 'string' THEN 'text' WHEN 'boolean' THEN NEW.value ELSE JSONB_TYPEOF(CAST(NEW.value AS JSONB)) END IN ('integer', 'real') OR (NEW.key = 'gamble_chance' AND NOT CAST(NEW.value AS DOUBLE PRECISION) BETWEEN 0 AND 100) OR (NEW.key = 'gamble_return' AND NOT CAST(NEW.value AS DOUBLE PRECISION) BETWEEN 0 AND 10000)) THEN
            RAISE EXCEPTION USING MESSAGE = 'Gamble setting is outside its supported range', ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_settings_gamble_validate_insert" BEFORE INSERT ON "settings" FOR EACH ROW EXECUTE FUNCTION "trg_settings_gamble_validate_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_settings_gamble_validate_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.key IN ('gamble_chance', 'gamble_return')) THEN
        IF (CASE WHEN PG_INPUT_IS_VALID(NEW.value, 'json') THEN 1 ELSE 0 END = 0) THEN
