CREATE OR REPLACE FUNCTION "trg_settings_legal_max_clamp_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.key = 'legal_max_rate') THEN
        UPDATE bank_products SET interest_rate = LEAST(interest_rate, COALESCE((SELECT MIN(c.legal_max_rate) FROM country_currencies AS c WHERE c.currency_code = liability.quote_currency), CAST(NEW.value AS DOUBLE PRECISION))) WHERE liability.kind = 'loan';
        UPDATE loans SET contract_rate = LEAST(contract_rate, COALESCE((SELECT c.legal_max_rate FROM country_currencies AS c WHERE c.nationality = loans.rate_nationality), CAST(NEW.value AS DOUBLE PRECISION))), contract_effective_rate = NULL, contract_apr = NULL;
    END IF;
    RETURN NULL;
END $$;
CREATE TRIGGER "trg_settings_legal_max_clamp" AFTER UPDATE OF "value" ON "settings" FOR EACH ROW EXECUTE FUNCTION "trg_settings_legal_max_clamp_fn"();
CREATE OR REPLACE FUNCTION "trg_settings_rate_history_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.key IN ('base_rate', 'legal_max_rate')) THEN
        INSERT INTO country_rate_history (nationality, rate_key, annual_percent, effective_epoch, changed_by) VALUES ('*', NEW.key, CAST(NEW.value AS DOUBLE PRECISION), ((EXTRACT(EPOCH FROM CURRENT_TIMESTAMP) / 86400.0 + 2440587.5) - 2440587.5) * 86400.0, 'database');
    END IF;
    RETURN NULL;
END $$;
