CREATE OR REPLACE FUNCTION "trg_settings_rate_history_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.key IN ('base_rate', 'legal_max_rate') AND (OLD.key <> NEW.key OR CAST(OLD.value AS DOUBLE PRECISION) <> CAST(NEW.value AS DOUBLE PRECISION))) THEN
        INSERT INTO country_rate_history (nationality, rate_key, annual_percent, effective_epoch, changed_by) VALUES ('*', NEW.key, CAST(NEW.value AS DOUBLE PRECISION), ((EXTRACT(EPOCH FROM CURRENT_TIMESTAMP) / 86400.0 + 2440587.5) - 2440587.5) * 86400.0, 'database');
    END IF;
    RETURN NULL;
END $$;
