BEGIN
    IF ((NEW."gross_amount" IS NOT DISTINCT FROM NULL OR NEW."gross_amount" <> ROUND(CAST(((COALESCE(NEW."gross_amount", 0)) + CASE WHEN (COALESCE(NEW."gross_amount", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT))) OR (NEW."tax_amount" IS NOT DISTINCT FROM NULL OR NEW."tax_amount" <> ROUND(CAST(((COALESCE(NEW."tax_amount", 0)) + CASE WHEN (COALESCE(NEW."tax_amount", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT))) OR (NEW."net_amount" IS NOT DISTINCT FROM NULL OR NEW."net_amount" <> ROUND(CAST(((COALESCE(NEW."net_amount", 0)) + CASE WHEN (COALESCE(NEW."net_amount", 0)) >= 0 THEN 1e-12 ELSE -1e-12 END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT)))) THEN
        NEW."gross_amount" := ROUND(CAST(((COALESCE(NEW."gross_amount", 0)) + CASE WHEN (COALESCE(NEW."gross_amount", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
        NEW."tax_amount" := ROUND(CAST(((COALESCE(NEW."tax_amount", 0)) + CASE WHEN (COALESCE(NEW."tax_amount", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
        NEW."net_amount" := ROUND(CAST(((COALESCE(NEW."net_amount", 0)) + CASE WHEN (COALESCE(NEW."net_amount", 0)) >= 0 THEN 1e-12 ELSE (0 - 1e-12) END) AS DECIMAL), CAST(COALESCE((SELECT decimal_places FROM currencies WHERE code = (NEW.currency_code)), 0) AS INT));
    END IF;
    RETURN NEW;
END $$;
