CREATE OR REPLACE FUNCTION "trg_tax_transactions_legacy_from_minor_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.gross_amount <> (CAST(NEW.gross_amount_minor_units AS DECIMAL) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) OR NEW.tax_amount <> (CAST(NEW.tax_amount_minor_units AS DECIMAL) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) OR NEW.net_amount <> (CAST(NEW.net_amount_minor_units AS DECIMAL) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END))) THEN
        NEW."gross_amount" := (CAST(NEW.gross_amount_minor_units AS DECIMAL) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END));
        NEW."tax_amount" := (CAST(NEW.tax_amount_minor_units AS DECIMAL) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END));
        NEW."net_amount" := (CAST(NEW.net_amount_minor_units AS DECIMAL) / (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END));
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_tax_transactions_legacy_from_minor" BEFORE UPDATE OF "gross_amount_minor_units", "tax_amount_minor_units", "net_amount_minor_units" ON "tax_transactions" FOR EACH ROW EXECUTE FUNCTION "trg_tax_transactions_legacy_from_minor_fn"();
CREATE OR REPLACE FUNCTION "trg_tax_transactions_minor_from_legacy_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    NEW."gross_amount_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.gross_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
    NEW."tax_amount_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.tax_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
    NEW."net_amount_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.net_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_tax_transactions_minor_from_legacy_insert" BEFORE INSERT ON "tax_transactions" FOR EACH ROW EXECUTE FUNCTION "trg_tax_transactions_minor_from_legacy_insert_fn"();
CREATE OR REPLACE FUNCTION "trg_tax_transactions_minor_from_legacy_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NEW.gross_amount_minor_units <> TRUNC(ROUND(CAST((COALESCE(NEW.gross_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) OR NEW.tax_amount_minor_units <> TRUNC(ROUND(CAST((COALESCE(NEW.tax_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) OR NEW.net_amount_minor_units <> TRUNC(ROUND(CAST((COALESCE(NEW.net_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)))) THEN
        NEW."gross_amount_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.gross_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
        NEW."tax_amount_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.tax_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
        NEW."net_amount_minor_units" := TRUNC(ROUND(CAST((COALESCE(NEW.net_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT)));
    END IF;
    RETURN NEW;
END $$;
