CREATE OR REPLACE FUNCTION "trg_tax_transactions_minor_units_guard_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (NOT (NEW.gross_amount_minor_units = TRUNC(NEW.gross_amount_minor_units)) OR NOT (NEW.tax_amount_minor_units = TRUNC(NEW.tax_amount_minor_units)) OR NOT (NEW.net_amount_minor_units = TRUNC(NEW.net_amount_minor_units)) OR TRUNC(ROUND(CAST((COALESCE(NEW.gross_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) <> (TRUNC(ROUND(CAST((COALESCE(NEW.tax_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) + TRUNC(ROUND(CAST((COALESCE(NEW.net_amount, 0) * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.currency_code), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))))) THEN
        RAISE EXCEPTION USING MESSAGE = 'tax transaction currency minor units are invalid or unbalanced', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "trg_tax_transactions_minor_units_guard_insert" BEFORE INSERT ON "tax_transactions" FOR EACH ROW EXECUTE FUNCTION "trg_tax_transactions_minor_units_guard_insert_fn"();
