CREATE OR REPLACE FUNCTION "validate_treasury_bond_insert_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (TRUNC(ROUND(CAST((NEW.face_value * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) <= 0 OR TRUNC(ROUND(CAST((NEW.total_supply * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) <= 0 OR TRUNC(ROUND(CAST((NEW.total_supply * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) % TRUNC(ROUND(CAST((NEW.face_value * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) <> 0 OR TRUNC(ROUND(CAST((NEW.sold_amount * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) < 0 OR TRUNC(ROUND(CAST((NEW.sold_amount * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) > TRUNC(ROUND(CAST((NEW.total_supply * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) OR TRUNC(ROUND(CAST((NEW.sold_amount * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) % TRUNC(ROUND(CAST((NEW.face_value * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) <> 0) THEN
        RAISE EXCEPTION USING MESSAGE = '국채 발행한도와 판매액은 양의 액면가 배수여야 합니다.', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "validate_treasury_bond_insert" BEFORE INSERT ON "treasury_bond_products" FOR EACH ROW EXECUTE FUNCTION "validate_treasury_bond_insert_fn"();
CREATE OR REPLACE FUNCTION "validate_treasury_bond_update_fn"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (TRUNC(ROUND(CAST((NEW.face_value * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) <= 0 OR TRUNC(ROUND(CAST((NEW.total_supply * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) <= 0 OR TRUNC(ROUND(CAST((NEW.total_supply * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) % TRUNC(ROUND(CAST((NEW.face_value * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) <> 0 OR TRUNC(ROUND(CAST((NEW.sold_amount * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) < 0 OR TRUNC(ROUND(CAST((NEW.sold_amount * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) > TRUNC(ROUND(CAST((NEW.total_supply * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) OR TRUNC(ROUND(CAST((NEW.sold_amount * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) % TRUNC(ROUND(CAST((NEW.face_value * (CASE COALESCE((SELECT decimal_places FROM currencies WHERE code = NEW.quote_currency), 0) WHEN 0 THEN 1 WHEN 1 THEN 10 ELSE 100 END)) AS DECIMAL), CAST(0 AS INT))) <> 0) THEN
        RAISE EXCEPTION USING MESSAGE = '국채 발행한도와 판매액은 양의 액면가 배수여야 합니다.', ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;
CREATE TRIGGER "validate_treasury_bond_update" BEFORE UPDATE OF "face_value", "total_supply", "sold_amount", "quote_currency" ON "treasury_bond_products" FOR EACH ROW EXECUTE FUNCTION "validate_treasury_bond_update_fn"();
